/**
 * Pure logic for writing the minutes automatically after Stop: the "ready in about N s" estimate and the
 * once-only guard. No imports, so node:test can load it. Storage is passed in.
 */

/** Fewer words than this and nothing is generated by itself (the user can still press the button). */
export const AUTO_MIN_WORDS = 60;

export interface Sample {
  words: number;
  secs: number;
}

const MAX_SAMPLES = 5;
const MIN_ETA = 8;
const MAX_ETA = 240;

/** Seconds until ready: from the recent generation speed on this device, else a rough default. */
export function estimateSeconds(words: number, samples: readonly Sample[]): number {
  const w = Math.max(0, Math.floor(words));
  const good = samples.filter((s) => s.words > 0 && s.secs > 0 && Number.isFinite(s.secs)).slice(-MAX_SAMPLES);
  let est: number;
  if (good.length) {
    // Time has a fixed part (waiting for the model) and a part that grows with length; scale the average.
    const avgWords = good.reduce((n, s) => n + s.words, 0) / good.length;
    const avgSecs = good.reduce((n, s) => n + s.secs, 0) / good.length;
    const fixed = Math.min(avgSecs * 0.5, 10);
    est = fixed + ((avgSecs - fixed) * w) / Math.max(avgWords, 1);
  } else {
    est = 10 + w * 0.012;
  }
  return Math.round(Math.min(MAX_ETA, Math.max(MIN_ETA, est)));
}

export function addSample(samples: readonly Sample[], s: Sample): Sample[] {
  if (!(s.words > 0) || !(s.secs > 0)) return [...samples].slice(-MAX_SAMPLES);
  return [...samples, { words: Math.round(s.words), secs: Math.round(s.secs * 10) / 10 }].slice(-MAX_SAMPLES);
}

export function parseSamples(raw: string | null): Sample[] {
  try {
    const v = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(v)) return [];
    return v
      .filter((x): x is Sample => !!x && typeof x.words === "number" && typeof x.secs === "number")
      .slice(-MAX_SAMPLES);
  } catch {
    return [];
  }
}

/** "about 20 seconds" / "about 1 minute". */
export function etaLabel(secs: number): string {
  if (secs < 90) return `about ${Math.max(5, Math.round(secs / 5) * 5)} seconds`;
  const m = Math.round(secs / 60);
  return `about ${m} ${m === 1 ? "minute" : "minutes"}`;
}

/* ---------- once-only guard ---------- */

export type JobState = "queued" | "running" | "done" | "failed";
export interface Entry {
  state: JobState;
  words: number;
  at: number;
  /** Who holds the "running" state; used to confirm a claim won the race between tabs. */
  token?: string;
}
export type Book = Record<string, Entry>;

/** A run that has not finished after this long is assumed dead (tab closed), so another may take over. */
export const STALE_RUNNING_MS = 10 * 60_000;
const KEEP_MS = 14 * 24 * 3600_000;

export interface KV {
  get(): string | null;
  set(value: string): void;
}

export function readBook(kv: KV, now: number): Book {
  let book: Book = {};
  try {
    const raw = kv.get();
    const v = raw ? JSON.parse(raw) : {};
    if (v && typeof v === "object" && !Array.isArray(v)) book = v as Book;
  } catch {
    book = {};
  }
  for (const [id, e] of Object.entries(book)) {
    if (!e || typeof e !== "object" || typeof e.at !== "number" || now - e.at > KEEP_MS) delete book[id];
  }
  return book;
}

function write(kv: KV, book: Book): void {
  try {
    kv.set(JSON.stringify(book));
  } catch {
    /* storage full or blocked: the server-side guard still prevents a second document */
  }
}

/** Remember a meeting that should be written up. A meeting already in the book (any state) is never queued again. */
export function enqueue(kv: KV, id: string, words: number, now: number): boolean {
  if (words < AUTO_MIN_WORDS) return false;
  const book = readBook(kv, now);
  if (book[id]) return false;
  book[id] = { state: "queued", words, at: now };
  write(kv, book);
  return true;
}

/** Take the job. True for exactly one caller; others see running/done/failed and get false. */
export function claim(kv: KV, id: string, now: number, token: string): boolean {
  const book = readBook(kv, now);
  const e = book[id];
  if (!e) return false;
  const free = e.state === "queued" || (e.state === "running" && now - e.at > STALE_RUNNING_MS);
  if (!free) return false;
  book[id] = { ...e, state: "running", at: now, token };
  write(kv, book);
  // Another tab may have written between our read and write; the last writer wins, so confirm it was us.
  return readBook(kv, now)[id]?.token === token;
}

export function settle(kv: KV, id: string, state: "done" | "failed" | "queued", now: number): void {
  const book = readBook(kv, now);
  const e = book[id];
  if (!e) return;
  book[id] = { state, words: e.words, at: now };
  write(kv, book);
}

export function queuedIds(kv: KV, now: number): string[] {
  return Object.entries(readBook(kv, now))
    .filter(([, e]) => e.state === "queued" || (e.state === "running" && now - e.at > STALE_RUNNING_MS))
    .map(([id]) => id);
}

export function entryFor(kv: KV, id: string, now: number): Entry | null {
  return readBook(kv, now)[id] ?? null;
}

/** Everything the runner needs to decide, kept pure so it can be tested. */
export function shouldRunNow(o: {
  flagOn: boolean;
  online: boolean;
  signedIn: boolean;
  recording: boolean;
}): boolean {
  return o.flagOn && o.online && o.signedIn && !o.recording;
}
